/**
 * Global GitButler (`but`) + Entire bridge plugin for OpenCode 2 & OpenChamber
 * (`~/.config/opencode/plugins/entire-but-bridge.js`).
 *
 * Why PATH-shim injection instead of rewriting `shell.command`:
 * OpenCode 2's portable shell permission scanner runs AFTER `ctx.shell.hook("create.before")`
 * and rejects inline shell functions/traps (`dynamic-execution`). By leaving `shell.command`
 * completely untouched and prepending `~/.config/opencode/entire-but-shim` to `shell.env.PATH`
 * whenever an Entire-enabled repository is targeted:
 * 1. OpenCode's portable shell scanner & permission prompts see the exact clean command.
 * 2. `atuin.ts` records the exact clean command in shell history.
 * 3. Subshells, scripts, and chained `but commit ... && but push ...` commands all hit the
 *    POSIX shims (`entire-but-shim/but` and `entire-but-shim/entire`) transparently.
 */

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const DEFAULT_SHIM_DIR = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "..",
  "entire-but-shim",
);

export function findEntireRepoRoot(startDir, fsImpl = fs) {
  if (!startDir || typeof startDir !== "string") return null;
  let current = path.resolve(startDir);
  for (let depth = 0; depth < 32; depth += 1) {
    const settingsPath = path.join(current, ".entire", "settings.json");
    try {
      if (fsImpl.existsSync(settingsPath)) {
        const parsed = JSON.parse(fsImpl.readFileSync(settingsPath, "utf8"));
        if (parsed?.enabled === true) return current;
        return null;
      }
    } catch {
      return null;
    }
    const parent = path.dirname(current);

