269: export async function checkBranchCheckpoints({ branch, execFileAsync = defaultExecFileAsync }) {
270:   const checks = [];
271: 
272:   // 1. Verify commits on <branch> ahead of origin/main (or main) carry Entire-Checkpoint trailers
273:   let logRes = await runCmd(execFileAsync, "git", [
274:     "log",
275:     `origin/main..${branch}`,
276:     "--no-merges",
277:     "--format=%H\t%(trailers:key=Entire-Checkpoint,valueonly)",
278:   ]);
279:   if (!logRes.ok) {
280:     logRes = await runCmd(execFileAsync, "git", [
281:       "log",
282:       `main..${branch}`,
283:       "--no-merges",
284:       "--format=%H\t%(trailers:key=Entire-Checkpoint,valueonly)",
285:     ]);
286:   }
287: 
288:   if (!logRes.ok) {
289:     checks.push({
290:       name: "gate.entire_checkpoint_trailers",
291:       status: "warn",
292:       detail: `Could not inspect commits on ${branch}: ${logRes.stderr}`,
293:     });
294:   } else {
295:     const lines = logRes.stdout ? logRes.stdout.split("\n").filter(Boolean) : [];
296:     const withCp = lines.filter((line) => {
297:       const parts = line.split("\t");
298:       return (parts[1] ?? "").trim().length > 0;
299:     });
300:     if (lines.length === 0) {
301:       checks.push({
302:         name: "gate.entire_checkpoint_trailers",
303:         status: "warn",
304:         detail: `No unmerged commits found on ${branch} ahead of main`,
305:       });
306:     } else if (withCp.length === 0) {
307:       checks.push({
308:         name: "gate.entire_checkpoint_trailers",
309:         status: "fail",
310:         detail: `0 of ${lines.length} commit(s) on ${branch} have an Entire-Checkpoint trailer`,
311:       });
312:     } else {
313:       checks.push({
314:         name: "gate.entire_checkpoint_trailers",
315:         status: "pass",
316:         detail: `${withCp.length}/${lines.length} commit(s) on ${branch} have Entire-Checkpoint trailers`,
317:       });
318:     }
319:   }
320: 
321:   // 2. Verify condensed checkpoints exist on the branch
322:   const cpListRes = await runCmd(execFileAsync, "entire", ["checkpoint", "list", "--json"]);
323:   if (!cpListRes.ok) {
324:     checks.push({
325:       name: "gate.entire_checkpoints",
326:       status: "warn",
327:       detail: `Could not query 'entire checkpoint list --json': ${cpListRes.stderr}`,
328:     });
329:   } else {
330:     let cps = [];
331:     try {
332:       const parsed = JSON.parse(cpListRes.stdout || "[]");
333:       cps = Array.isArray(parsed) ? parsed : [];
334:     } catch {
335:       cps = [];
336:     }
337:     checks.push({
338:       name: "gate.entire_checkpoints",
339:       status: cps.length > 0 ? "pass" : "fail",
340:       detail:
341:         cps.length > 0
342:           ? `${cps.length} Entire checkpoint(s) recorded on branch`
343:           : `0 Entire checkpoints recorded on ${branch} (ensure Pi/Entire hooks are active before committing)`,
344:     });
345:   }
346: 
347:   // 3. Verify no outgoing checkpoints are left unpushed
348:   const outgoingRes = await runCmd(execFileAsync, "entire", ["checkpoint", "list", "--outgoing", "--json"]);
349:   if (outgoingRes.ok) {
350:     try {
351:       const parsed = JSON.parse(outgoingRes.stdout || '{"checkpoints":[]}');
352:       const waiting = Array.isArray(parsed?.checkpoints) ? parsed.checkpoints : [];
353:       if (waiting.length > 0) {
354:         const first = waiting[0];
355:         const example = first.commit ? `${first.checkpoint_id}@${first.commit}` : first.checkpoint_id;
356:         checks.push({
357:           name: "gate.entire_checkpoints_pushed",
358:           status: "fail",
359:           detail: `${waiting.length} checkpoint(s) not yet pushed to remote (run: entire checkpoint push ${example} --json)`,
360:         });
361:       } else {
362:         checks.push({
363:           name: "gate.entire_checkpoints_pushed",
364:           status: "pass",
365:           detail: "All local Entire checkpoints are pushed to remote",
366:         });
367:       }
368:     } catch {
369:       // ignore parse errors on non-git-refs backends
370:     }
371:   }
372: 
373:   return checks;
374: }
