453: async function runCmd(execFileAsync, bin, args, timeout = 15000) {
454:   try {
455:     const { stdout = "", stderr = "" } = await execFileAsync(bin, args, {
456:       timeout,
457:       env: process.env,
458:     });
459:     return { ok: true, stdout: String(stdout).trim(), stderr: String(stderr).trim(), code: 0 };
460:   } catch (err) {
461:     return {
462:       ok: false,
463:       stdout: String(err?.stdout ?? "").trim(),
464:       stderr: String(err?.stderr ?? err?.message ?? "").trim(),
465:       code: err?.code ?? 1,
466:     };
467:   }
468: }
